// @vitest-environment jsdom
/**
 * Golden parity for DOCX: records generated by the Python engine from the
 * byte-identical demo fixtures must be reproduced field for field, and the
 * tracked-changes refusal must refuse like the engine refuses.
 */

import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";

import { diffDocx } from "../src/core/docxDiff";
import { DocxTrackedChangesError, extractDocx } from "../src/extract/docx";

const demo = (f: string) => readFileSync(resolve(import.meta.dirname, "../public/demo", f));
const golden = (f: string) => JSON.parse(readFileSync(resolve(import.meta.dirname, "golden", f), "utf8"));

describe("golden parity with the Python engine", () => {
  it("meeting-notes pair: paragraph edits + inserted table row", async () => {
    const oldD = await extractDocx(demo("meeting-notes.docx"), "meeting-notes.docx");
    const newD = await extractDocx(demo("meeting-notes-v2.docx"), "meeting-notes-v2.docx");
    expect(diffDocx(oldD, newD, "meeting-notes.docx")).toEqual(golden("meeting-notes.json"));
  });

  it("identical file diffs to nothing", async () => {
    const a = await extractDocx(demo("meeting-notes.docx"), "meeting-notes.docx");
    const b = await extractDocx(demo("meeting-notes.docx"), "meeting-notes.docx");
    expect(diffDocx(a, b, "meeting-notes.docx")).toEqual([]);
  });
});

describe("tracked-changes refusal", () => {
  it("refuses a revision-marked file with a clean message, never a partial diff", async () => {
    await expect(extractDocx(demo("meeting-notes-tracked.docx"), "meeting-notes-tracked.docx")).rejects.toThrow(
      DocxTrackedChangesError,
    );
    await expect(extractDocx(demo("meeting-notes-tracked.docx"), "meeting-notes-tracked.docx")).rejects.toThrow(
      /meeting-notes-tracked\.docx: tracked changes present; accept or reject them in Word first/,
    );
  });
});
